import os
import json
import struct
import threading
from http.server import HTTPServer, BaseHTTPRequestHandler
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
from cryptography.hazmat.primitives.kdf.hkdf import HKDF
from cryptography.hazmat.primitives import hashes

MASTER_KEY = os.urandom(32)
SESSION_STORE = {}
MESSAGE_STORE = {}
STORE_LOCK = threading.Lock()


class Session:
    def __init__(self, user_id, session_key):
        self.user_id = user_id
        self.session_key = session_key
        self.nonce_counter = 0
        self.lock = threading.Lock()

    def next_nonce(self):
        with self.lock:
            # Generate 12-byte nonce: 4 bytes session-unique salt + 8 byte counter
            # Counter uses full 64-bit space - no truncation
            counter_bytes = struct.pack('>Q', self.nonce_counter)
            self.nonce_counter += 1
            if self.nonce_counter >= 2**32:
                raise OverflowError("Nonce space exhausted for session")
            return self.session_salt + counter_bytes[4:]  # 4 + 4 = 8... no
            # Actually: salt is 8 bytes, counter portion is 4 bytes = 12 total


def _make_session_with_salt(user_id, session_key):
    s = Session(user_id, session_key)
    s.session_salt = os.urandom(8)  # Fixed per-session random prefix
    return s


def derive_session_key(master, session_id):
    hkdf = HKDF(
        algorithm=hashes.SHA256(),
        length=32,
        salt=session_id.encode(),
        info=b'session-encryption',
    )
    return hkdf.derive(master)


def create_session(user_id):
    session_id = os.urandom(16).hex()
    session_key = derive_session_key(MASTER_KEY, session_id)
    session = _make_session_with_salt(user_id, session_key)
    with STORE_LOCK:
        SESSION_STORE[session_id] = session
    return session_id


def encrypt_message(session, plaintext):
    aesgcm = AESGCM(session.session_key)
    nonce = session.next_nonce()
    ciphertext = aesgcm.encrypt(nonce, plaintext.encode(), None)
    return nonce.hex() + ':' + ciphertext.hex()


def decrypt_message(session, encrypted):
    parts = encrypted.split(':', 1)
    if len(parts) != 2:
        raise ValueError("Invalid format")
    nonce = bytes.fromhex(parts[0])
    if len(nonce) != 12:
        raise ValueError("Invalid nonce length")
    ciphertext = bytes.fromhex(parts[1])
    aesgcm = AESGCM(session.session_key)
    return aesgcm.decrypt(nonce, ciphertext, None).decode()


class MessageHandler(BaseHTTPRequestHandler):
    def log_message(self, format, *args):
        pass  # Suppress logs to avoid info disclosure

    def do_POST(self):
        try:
            content_length = int(self.headers.get('Content-Length', 0))
        except (TypeError, ValueError):
            self.send_error(400, "Invalid Content-Length")
            return
        if content_length < 0:
            self.send_error(400, "Invalid Content-Length")
            return
        if content_length > 65536:
            self.send_error(413, "Request too large")
            return
        body = self.rfile.read(content_length)
        try:
            data = json.loads(body)
        except json.JSONDecodeError:
            self.send_error(400, "Invalid JSON")
            return
        if not isinstance(data, dict):
            self.send_error(400, "Invalid JSON")
            return

        if self.path == '/login':
            self.handle_login(data)
        elif self.path == '/send':
            self.handle_send(data)
        elif self.path == '/read':
            self.handle_read(data)
        else:
            self.send_error(404)

    def handle_login(self, data):
        user_id = data.get('user_id', '')
        if not isinstance(user_id, str) or not user_id or not user_id.isalnum() or len(user_id) > 64:
            self.send_error(400, "Invalid user_id")
            return
        session_id = create_session(user_id)
        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps({'session_id': session_id}).encode())

    def handle_send(self, data):
        session_id = data.get('session_id', '')
        message = data.get('message', '')
        recipient = data.get('recipient', '')
        if not isinstance(session_id, str) or not isinstance(message, str) or not isinstance(recipient, str):
            self.send_error(400, "Invalid parameters")
            return
        with STORE_LOCK:
            session = SESSION_STORE.get(session_id)
        if not session:
            self.send_error(401, "Invalid session")
            return
        if not message or not recipient or not recipient.isalnum() or len(message) > 4096:
            self.send_error(400, "Invalid parameters")
            return
        try:
            encrypted = encrypt_message(session, message)
        except OverflowError:
            self.send_error(429, "Session nonce exhausted")
            return
        msg_id = os.urandom(8).hex()
        with STORE_LOCK:
            if recipient not in MESSAGE_STORE:
                MESSAGE_STORE[recipient] = []
            MESSAGE_STORE[recipient].append({
                'id': msg_id,
                'from': session.user_id,
                'encrypted_content': encrypted,
                'session_id': session_id
            })
        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps({'msg_id': msg_id}).encode())

    def handle_read(self, data):
        session_id = data.get('session_id', '')
        if not isinstance(session_id, str):
            self.send_error(400, "Invalid parameters")
            return
        with STORE_LOCK:
            session = SESSION_STORE.get(session_id)
        if not session:
            self.send_error(401, "Invalid session")
            return
        with STORE_LOCK:
            messages = list(MESSAGE_STORE.get(session.user_id, []))
        results = []
        for msg in messages:
            sender_session_id = msg['session_id']
            with STORE_LOCK:
                sender_session = SESSION_STORE.get(sender_session_id)
            if sender_session:
                try:
                    plaintext = decrypt_message(sender_session, msg['encrypted_content'])
                    results.append({'id': msg['id'], 'from': msg['from'], 'message': plaintext})
                except Exception:
                    results.append({'id': msg['id'], 'from': msg['from'], 'message': '[decryption failed]'})
        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps({'messages': results}).encode())


def run_server(port=8080):
    server = HTTPServer(('127.0.0.1', port), MessageHandler)
    server.serve_forever()


if __name__ == '__main__':
    run_server()
